<section class="gamification-list"><header><h1><?php echo $this->lang('Teams') ?></h1></header><div class="gamification-grid"><?php foreach ($teams as $team): ?><article class="gamification-card gamification-team-card<?php echo $team['banner_path'] ? ' has-cover' : '' ?>" style="--team-color:<?php echo utf8_htmlentities($team['color']) ?>"><?php if ($team['banner_path']): ?><div class="gamification-team-cover"><img src="<?php echo utf8_htmlentities(url($team['banner_path'])) ?>" alt="" loading="lazy" /></div><?php endif ?><div class="gamification-team-heading"><?php if ($team['logo_path']): ?><img class="gamification-team-logo" src="<?php echo utf8_htmlentities(url($team['logo_path'])) ?>" alt="" loading="lazy" /><?php endif ?><h2><a href="<?php echo url('teams/'.$team['team_id'].'/'.$team['slug']) ?>"><?php echo utf8_htmlentities($team['title']) ?></a></h2></div><p><?php echo nl2br(utf8_htmlentities($team['description'])) ?></p><small><?php echo $this->lang('%d members', (int)$team['member_count']) ?></small></article><?php endforeach ?></div></section>
